package com.quickmanager.debug;

import org.springframework.security.crypto.bcrypt.BCrypt;

public class GenerateHashes {
    public static void main(String[] args) {
        String[][] data = new String[][]{
            {"admin", "Admin@123"},
            {"ketoan.lan", "Lan@123"},
            {"thukho.bao", "Bao@123"},
            {"thungan.ha", "Ha@123"},
            {"thungan.nam", "Nam@123"},
            {"banhang.anh", "Anh@123"},
            {"banhang.tung", "Tung@123"},
            {"cskh.dung", "Dung@123"},
            {"giamsat.huy", "Huy@123"},
            {"linh.old", "Linh@123"}
        };

        for (String[] u : data) {
            String user = u[0];
            String pass = u[1];
            String hash = BCrypt.hashpw(pass, BCrypt.gensalt());
            System.out.println(user + ":" + hash);
        }
    }
}

package com.quickmanager.service;

import com.quickmanager.config.DBConnection;
import com.quickmanager.debug.Address;
import com.quickmanager.model.TaiKhoan;

import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.ResultSet;

public class AuthService {

    public static TaiKhoan login(String username, String password) {
        String sql = """
            SELECT TenDangNhap, MatKhau, MaNhanVien, VaiTro
            FROM TAI_KHOAN
            WHERE TenDangNhap = ?
            """;

        try (Connection con = DBConnection.getConnection();
             PreparedStatement st = con.prepareStatement(sql)) {

            st.setString(1, username);

            try (ResultSet rs = st.executeQuery()) {
                if (!rs.next()) {
                    return null;
                }

                String mkLuu = rs.getString("MatKhau");
                if (!PasswordUtils.ktraHash(password, mkLuu)) {
                    return null;
                }

                TaiKhoan tk = new TaiKhoan();
                tk.setTenDangNhap(rs.getString("TenDangNhap"));
                tk.setMaNhanVien(rs.getInt("MaNhanVien"));
                tk.setVaiTro(rs.getString("VaiTro"));
                return tk;
            }
        } catch (Exception e) {
            System.out.println("Lỗi đăng nhập: " + e.getMessage());
            Address.printAddress();
            return null;
        }
    }
}

package com.quickmanager.service;

import com.quickmanager.config.DBConnection;
import com.quickmanager.debug.Address;
import com.quickmanager.model.TaiKhoan;

import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.ResultSet;

public class AuthService {

    public static TaiKhoan login(String username, String password) {
        String sql = """
            SELECT TenDangNhap, MatKhau, MaNhanVien, VaiTro
            FROM TAI_KHOAN
            WHERE TenDangNhap = ?
            """;

        try (Connection con = DBConnection.getConnection();
             PreparedStatement st = con.prepareStatement(sql)) {

            st.setString(1, username);

            try (ResultSet rs = st.executeQuery()) {
                if (!rs.next()) {
                    return null;
                }

                String mkLuu = rs.getString("MatKhau");
                // Nếu mật khẩu lưu trong DB là hash (BCrypt) thì kiểm tra bình thường
                if (PasswordUtils.ktraHash(password, mkLuu)) {
                    // ok
                } else {
                    // Nếu mật khẩu trong DB chưa được hash (lưu plaintext),
                    // kiểm tra trực tiếp và nếu đúng thì migrate: hash và cập nhật lại DB
                    boolean migrated = false;
                    if (mkLuu != null && mkLuu.equals(password)) {
                        String newHash = PasswordUtils.hash(password);
                        String updSql = "UPDATE TAI_KHOAN SET MatKhau = ? WHERE TenDangNhap = ?";
                        try (Connection con2 = DBConnection.getConnection();
                             PreparedStatement pst = con2.prepareStatement(updSql)) {
                            pst.setString(1, newHash);
                            pst.setString(2, username);
                            pst.executeUpdate();
                            migrated = true;
                        } catch (Exception ex) {
                            System.out.println("Không cập nhật được hash mật khẩu: " + ex.getMessage());
                        }
                    }

                    if (!migrated) {
                        // không hợp lệ
                        return null;
                    }
                }

                TaiKhoan tk = new TaiKhoan();
                tk.setTenDangNhap(rs.getString("TenDangNhap"));
                tk.setMaNhanVien(rs.getInt("MaNhanVien"));
                tk.setVaiTro(rs.getString("VaiTro"));
                return tk;
            }
        } catch (Exception e) {
            System.out.println("Lỗi đăng nhập: " + e.getMessage());
            Address.printAddress();
            return null;
        }
    }
}
